    // the icon as a picture in one colour, for the controls that take no shape of ours (the side pane)
    public static Microsoft.UI.Xaml.Media.Imaging.SvgImageSource Picture(string name, Windows.UI.Color ink, double stroke = 1.75)
    {
        var source = new Microsoft.UI.Xaml.Media.Imaging.SvgImageSource { RasterizePixelWidth = 60, RasterizePixelHeight = 60 };
        var svg = FormattableString.Invariant($"<svg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24'><path d='{Paths[name]}' fill='none' stroke='#{ink.R:X2}{ink.G:X2}{ink.B:X2}' stroke-width='{stroke}' stroke-linecap='round' stroke-linejoin='round'/></svg>");
        var stream = new Windows.Storage.Streams.InMemoryRandomAccessStream();
        _ = Fill();
        return source;
        async Task Fill()
        {
            await stream.WriteAsync(System.Runtime.InteropServices.WindowsRuntime.WindowsRuntimeBufferExtensions.AsBuffer(System.Text.Encoding.UTF8.GetBytes(svg)));
            stream.Seek(0);
            await source.SetSourceAsync(stream);
        }
    }

    public static IReadOnlyCollection<string> Names => Paths.Keys;

    public static Geometry Geometry(string name) =>
        (Geometry)XamlBindingHelper.ConvertValue(typeof(Geometry), Paths.TryGetValue(name, out var d) ? d : Paths["puzzle"]);

    // the icon as an element: size in pixels; no brush takes the soft text colour
    public static FrameworkElement Icon(string name, double size = 16, Brush? brush = null, double stroke = 2) =>
        new LucideIcon { Kind = name, Size = size, Stroke = brush ?? App.Brush("ApexSoftTextBrush"), StrokeWidth = stroke };
}

// A Lucide icon for XAML and code: Kind is its name ("folder"), Size its width and height, Stroke its colour.
public sealed partial class LucideIcon : Grid
{
    readonly Microsoft.UI.Xaml.Shapes.Path _path = new()
    {
        StrokeThickness = 2, StrokeLineJoin = PenLineJoin.Round, StrokeStartLineCap = PenLineCap.Round, StrokeEndLineCap = PenLineCap.Round, Width = 24, Height = 24,
    };

    public LucideIcon()
    {
        var canvas = new Canvas { Width = 24, Height = 24 };
        canvas.Children.Add(_path);
        Children.Add(new Viewbox { Child = canvas });
        IsHitTestVisible = false;
        Width = Height = 16;
        _path.Stroke = App.Brush("ApexSoftTextBrush");
    }

    public string Kind { get => (string)GetValue(KindProperty); set => SetValue(KindProperty, value); }
    public static readonly DependencyProperty KindProperty = DependencyProperty.Register(nameof(Kind), typeof(string), typeof(LucideIcon),
        new PropertyMetadata("", (d, e) => ((LucideIcon)d)._path.Data = Lucide.Geometry((string)e.NewValue)));

    public double Size { get => Width; set { Width = value; Height = value; } }

    public Brush Stroke { get => (Brush)GetValue(StrokeProperty); set => SetValue(StrokeProperty, value); }
    public static readonly DependencyProperty StrokeProperty = DependencyProperty.Register(nameof(Stroke), typeof(Brush), typeof(LucideIcon),
        new PropertyMetadata(null, (d, e) => ((LucideIcon)d)._path.Stroke = (Brush)e.NewValue));

    public double StrokeWidth { get => _path.StrokeThickness; set => _path.StrokeThickness = value; }
}
